// App logo bitmaps, embedded as base64 to avoid bundle path resolution
// (same reasoning as the original tray icon constant in main.ts).
//
// Regenerate after changing logo/ assets:
//   base64 -w0 logo/tray-32.png          -> TRAY_ICON_BASE64.dark
//   base64 -w0 logo/light/tray-32.png    -> TRAY_ICON_BASE64.light
//   base64 -w0 logo/app-256.png          -> WINDOW_ICON_BASE64.dark
//   base64 -w0 logo/light/app-256.png    -> WINDOW_ICON_BASE64.light
import type { LogoId } from "../../shared/ipc/schema.js";

/** 32px tray icons per logo variant. */
export const TRAY_ICON_BASE64: Record<LogoId, string> = {
  dark: "",
  light: "",
};

/**
 * 256px window/dock icons per logo variant. 256px so the taskbar/dock stays
 * sharp on hi-dpi displays; note the packaged icon (build/icon.*) is used
 * whenever the default logo is active and no runtime override is applied.
 */
export const WINDOW_ICON_BASE64: Record<LogoId, string> = {
  dark: "",
  light: "",
};
